const e="Transfer Credit Policies",t={verified:!1,lastEdited:"9/9/2026",branch:"main",tablesPresent:0,tablesConsumed:0,tablesOnPage:0,tablesExcluded:0,sourceUrl:"https://catalog.northeastern.edu/graduate/professional-studies/academic-policies-procedures/transfer-credit-policies/",panes:[""],planOfStudyCourses:[],verification:{level:"partial",kind:"grad",score:.83,checkedAt:"2026-09-10",sourceUrl:"https://catalog.northeastern.edu/graduate/professional-studies/academic-policies-procedures/transfer-credit-policies/",sourcesAvailable:["requirement-tables","course-catalog"],counters:{tablesUnaccounted:0,leakedMarkers:0,unenumeratedSections:2,duplicateSectionTitles:0,duplicateConcentrationTitles:0,zeroTotal:1,unknownCourses:0,planUnexplained:0,impossibleSections:0},discrepancies:[{check:"missing-total-credits",severity:"medium",message:"the catalog page states no total credit requirement",detail:[{key:"noTotal"}],overflow:0},{check:"unenumerated-sections",severity:"info",message:"2 section(s) state a credit requirement whose courses the catalog does not list, so completion of those cannot be checked automatically",detail:[{key:"unenumeratedSection",params:{title:"2026-2027 Edition",sh:10}},{key:"unenumeratedSection",params:{title:"Prior Learning Assessment",sh:10}}],overflow:0}]}},a=0,i=2027,s=[{type:"SECTION",title:"2026-2027 Edition",creditsRequired:10,minRequirementCount:1,requirements:[],notes:["All graduate transfer credit awards are made on a case-by-case basis. Transfer credit awards are made for eligible courses successfully completed at regionally and programmatically accredited institutions. The Council for Higher Education Accreditation provides information about the organizations responsible for these two forms of accreditation. Official transcripts from all institutions should be sent directly to the College of Professional Studies Office of Admissions at the time of application.","Students seeking transfer credits earned at institutions outside the United States should submit an official English evaluation completed by an approved credential evaluator. Course descriptions and/or syllabi also should be translated into English and submitted to the College of Professional Studies Office of Admissions.","A maximum of 10 semester hours obtained at another institution may be accepted as transfer toward the degree, provided the credits consist of work taken at the graduate level for graduate credit, carry minimum grades of B (or 3.000 on a 4.000 scale), have been earned at an accredited institution or equivalent, and have not been used toward any baccalaureate or advanced degree or certificate of advanced graduate study at another institution.","Transfer credits must be no more than five academic years old at the time the student is admitted to graduate study. Courses older than five years will be accepted only in rare circumstances."]},{type:"SECTION",title:"Prior Learning Assessment",creditsRequired:10,minRequirementCount:1,requirements:[],notes:["Students may be eligible for prior learning assessment credit if they have accrued a foundation of knowledge and skills equivalent to the content of courses offered by the College of Professional Studies.","Awarded credits are incorporated into a student’s degree plan as transfer credits and are subject to Northeastern University’s residency requirement. PLA credit is limited to a maximum of 10 semester hours for graduate students. Acceptable credits for PLA review are determined from approved certificates, training, and a portfolio review of prior work experience. As part of consideration for PLA credits, faculty will evaluate and map learning outcomes and achievement in alignment with NECHE accreditation requirements.","Potential PLA credits should be considered and discussed as part of a student’s transfer credits at the time of enrollment. Interested students should contact their academic advisor for more information."]}],r={name:e,metadata:t,totalCreditsRequired:a,yearVersion:i,requirementSections:s};export{r as default,t as metadata,e as name,s as requirementSections,a as totalCreditsRequired,i as yearVersion};
